  cons_en = '["USD pricing","Build plan capped at 500 conversions/mo","Smart Traffic only on Experiment+","No blog or back-end","Learning curve for advanced A/B testing"]'::jsonb,
  use_cases = '["Tester 3-5 angles de promesse pour une offre avant de scaler la pub","Capturer des leads avec un lead magnet sur une page dédiée","Créer une page de vente pour une offre one-shot","Router automatiquement les visiteurs Google vs Meta vers la meilleure variante","Lancer une page d''inscription événement avec tracking conversion"]'::jsonb,
  use_cases_en = '["Test 3-5 promise angles before scaling paid ads","Capture leads with a dedicated lead magnet page","Build a sales page for a one-shot offer","Auto-route Google vs Meta traffic","Event signup page with conversion tracking"]'::jsonb,
  verdict = '{"keepIf":["Tu fais 1000€+/mois de pub payante","Tu lances régulièrement de nouvelles offres à valider","Tu veux tester sans monopoliser un dev"],"avoidIf":["Tu n''envoies pas de trafic payant — Webflow/Framer suffit","Ton site est déjà sur Wordpress + Elementor","Tu cherches un site complet avec blog/boutique"],"threshold":"Rentable dès 800-1000€/mois de budget pub : +15% de conversion couvre largement les 74-109$/mois."}'::jsonb,
  verdict_en = '{"keepIf":["You spend $1k+/mo on paid ads","You launch new offers regularly","You want to test without a dev"],"avoidIf":["No paid traffic","Wordpress + Elementor already","Need full site with blog/store"],"threshold":"Profitable from $800-1000/mo ad spend."}'::jsonb,
