  personas = '["marc","alix","claire"]'::jsonb,
  verticals = '["growth-ops","marketing-ops","conversion-ops"]'::jsonb,
  functional_needs = '["landing-pages","ab-testing","lead-capture"]'::jsonb,
  tool_type = 'satellite',
  prescription_quality = 'oui',
  seo = '{"metaTitle":"Unbounce avis 2026 : prix, A/B, Smart Traffic | Tooltrim","metaDescription":"Unbounce pour landing pages : 74$/mois, IA Smart Traffic +20% de conversion. Notre verdict, les limites réelles, et quand préférer Leadpages ou Framer."}'::jsonb,
