  verdict = '{"keepIf":["Tu fais 2+ présentations/mois","Tu veux un rendu propre sans être designer","Tu veux exporter en PPTX/PDF pour clients"],"avoidIf":["Pitch/Canva te suffit déjà","Charte graphique stricte non négociable","1 présentation tous les 6 mois"],"threshold":"Rentable dès 1 présentation/mois : 10$/mois vs 2-3h économisées à 50€/h."}'::jsonb,
