  '["marc","claire","alix","theo"]'::jsonb,
  '["productivity-ops","scheduling-ops"]'::jsonb,
  '["calendar","scheduling","focus-time","habits"]'::jsonb,
  'satellite','oui',
  '{"metaTitle":"Reclaim.ai avis 2026 : prix, IA agenda | Tooltrim","metaDescription":"Reclaim pour calendrier IA : 10$/mois, auto-planification dans Google Calendar. Notre verdict, les limites, et quand préférer Motion ou Calendly."}'::jsonb,
  '{"compare_price_monthly_eur":10,"compare_plan_name":"Starter","compare_plan_kind":"seat","price_reliability":"high","usage_sensitive":false,"location_sensitive":false,"cautions":["Prix en USD. Nécessite Google Calendar."],"source_domain":"reclaim.ai","verified_on":"2026-05-06","official_source_url":"https://reclaim.ai/pricing","verification_status":"official_verified"}'::jsonb,
  true),
